//! Project retention preferences belong to the application, not the selected index.
use crate::*;
use std::sync::Mutex;
use tauri::Emitter;
static WRITER:Mutex<()>=Mutex::new(());
#[derive(Clone,Debug,Serialize,Deserialize,PartialEq)]
#[serde(rename_all="camelCase",deny_unknown_fields,default)]
pub struct Preferences{pub version:u32,pub revision:u64,pub autosave_enabled:bool,pub interval_seconds:u64,pub always_save_on_exit:bool}
impl Default for Preferences{fn default()->Self{Self{version:1,revision:0,autosave_enabled:false,interval_seconds:60,always_save_on_exit:false}}}
#[derive(Deserialize,Default)]#[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct Patch{pub autosave_enabled:Option<bool>,pub interval_seconds:Option<u64>,pub always_save_on_exit:Option<bool>}
fn read(path:&Path)->Result<Preferences,String>{if !path.exists(){return Ok(Preferences::default());}if fs::metadata(path).map_err(|e|e.to_string())?.len()>8192{return Err("Не удалось прочитать настройки проектов.".into());}let mut p:Preferences=serde_json::from_slice(&fs::read(path).map_err(|e|e.to_string())?).map_err(|_|"Не удалось прочитать настройки проектов.")?;if p.version!=1{return Err("Версия настроек проектов не поддерживается.".into());}if ![30,60,180,300,600].contains(&p.interval_seconds){p.interval_seconds=60;}Ok(p)}
fn write(path:&Path,value:&Preferences)->Result<(),String>{let parent=path.parent().ok_or("Нет папки настроек")?;fs::create_dir_all(parent).map_err(|e|e.to_string())?;let temp=path.with_extension(format!("{}-{}.partial",std::process::id(),SystemTime::now().duration_since(UNIX_EPOCH).map_err(|e|e.to_string())?.as_nanos()));use std::io::Write;let mut file=fs::OpenOptions::new().write(true).create_new(true).open(&temp).map_err(|e|e.to_string())?;file.write_all(&serde_json::to_vec(value).map_err(|e|e.to_string())?).and_then(|_|file.sync_all()).map_err(|e|e.to_string())?;drop(file);
 #[cfg(windows)]{use std::os::windows::ffi::OsStrExt;use windows_sys::Win32::Storage::FileSystem::{MoveFileExW,MOVEFILE_REPLACE_EXISTING,MOVEFILE_WRITE_THROUGH};let from:Vec<u16>=temp.as_os_str().encode_wide().chain(Some(0)).collect();let to:Vec<u16>=path.as_os_str().encode_wide().chain(Some(0)).collect();if unsafe{MoveFileExW(from.as_ptr(),to.as_ptr(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH)}==0{let error=std::io::Error::last_os_error();let _=fs::remove_file(&temp);return Err(error.to_string());}}
 #[cfg(not(windows))]fs::rename(&temp,path).map_err(|e|e.to_string())?;Ok(())}
fn patch(path:&Path,change:Patch,legacy:Option<bool>,initialize:bool)->Result<Preferences,String>{let mut p=read(path)?;if initialize{if path.exists(){return Ok(p);}p.autosave_enabled=legacy.unwrap_or(false);}else{if let Some(v)=change.autosave_enabled{p.autosave_enabled=v;}if let Some(v)=change.always_save_on_exit{p.always_save_on_exit=v;}if let Some(v)=change.interval_seconds{if ![30,60,180,300,600].contains(&v){return Err("Недопустимый интервал автосохранения.".into());}p.interval_seconds=v;}}p.revision=p.revision.checked_add(1).ok_or("Предел версии настроек проектов")?;write(path,&p)?;Ok(p)}
#[tauri::command]
pub async fn get_project_preferences(app:tauri::AppHandle)->Result<Preferences,String>{tauri::async_runtime::spawn_blocking(move||{let _guard=WRITER.lock().map_err(|_|"Project preferences lock failed")?;read(&application_data_directory(&app)?.join("project-preferences.json"))}).await.map_err(|e|e.to_string())?}
#[tauri::command]
pub async fn initialize_project_preferences(app:tauri::AppHandle,legacy_autosave:Option<bool>)->Result<Preferences,String>{let owner=app.clone();let value=tauri::async_runtime::spawn_blocking(move||{let _guard=WRITER.lock().map_err(|_|"Project preferences lock failed")?;patch(&application_data_directory(&owner)?.join("project-preferences.json"),Patch::default(),legacy_autosave,true)}).await.map_err(|e|e.to_string())??;let _=app.emit("smart-photo-indexer:project-preferences-changed",&value);Ok(value)}
#[tauri::command]
pub async fn patch_project_preferences(app:tauri::AppHandle,patch:Patch)->Result<Preferences,String>{let owner=app.clone();let value=tauri::async_runtime::spawn_blocking(move||{let _guard=WRITER.lock().map_err(|_|"Project preferences lock failed")?;self::patch(&application_data_directory(&owner)?.join("project-preferences.json"),patch,None,false)}).await.map_err(|e|e.to_string())??;let _=app.emit("smart-photo-indexer:project-preferences-changed",&value);Ok(value)}
#[cfg(test)]mod tests{use super::*;
 fn file()->PathBuf{std::env::temp_dir().join(format!("smart-photo-project-prefs-{}-{}.json",std::process::id(),SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos()))}
 #[test]fn fresh_and_legacy_seed_once_with_merge_writes(){let p=file();assert_eq!(read(&p).unwrap(),Preferences::default());let first=patch(&p,Patch::default(),Some(true),true).unwrap();assert!(first.autosave_enabled);patch(&p,Patch{interval_seconds:Some(180),..Default::default()},None,false).unwrap();let actual=patch(&p,Patch{always_save_on_exit:Some(true),..Default::default()},None,false).unwrap();assert!(actual.autosave_enabled&&actual.always_save_on_exit);assert_eq!(actual.interval_seconds,180);assert_eq!(patch(&p,Patch::default(),Some(false),true).unwrap(),actual);fs::remove_file(p).unwrap();}
 #[test]fn invalid_patch_and_future_version_never_replace_existing_file(){let p=file();patch(&p,Patch::default(),None,true).unwrap();let before=fs::read(&p).unwrap();assert!(patch(&p,Patch{interval_seconds:Some(7),..Default::default()},None,false).is_err());assert_eq!(fs::read(&p).unwrap(),before);fs::write(&p,b"{\"version\":99}").unwrap();assert!(read(&p).is_err());fs::remove_file(p).unwrap();}
}
